(--teal);color:#fff;display:flex;align-items:center;justify-content:center;font-family:var(--font-h);font-size:.9rem;font-weight:400;text-decoration:none;overflow:hidden;}.tb-ava img{width:35px;height:35px;object-fit:cover;}.content{padding:24px 26px;flex:1;max-width:720px;}.sb-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:190;}.sb-overlay.show{display:block;}.notif-item{display:flex;gap:12px;align-items:flex-start;background:var(--white);border:1px solid var(--border);border-radius:var(--radius);padding:16px 18px;margin-bottom:10px;box-shadow:var(--shadow);text-decoration:none;transition:background .18s;cursor:pointer;}.notif-item.unread{background:#fffbf5;border-left:4px solid var(--orange);}.notif-item:hover{background:var(--cream2);}.n-icon{width:38px;height:38px;border-radius:10px;background:var(--cream2);display:flex;align-items:center;justify-content:center;font-size:1.1rem;flex-shrink:0;}.n-msg{font-size:.88rem;color:var(--ink2);line-height:1.5;margin-bottom:3px;}.n-time{font-size:.72rem;color:var(--muted);}.n-dot{width:8px;height:8px;border-radius:50%;background:var(--orange);flex-shrink:0;margin-top:6px;}.n-dot.read{background:var(--border);}.page-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:22px;flex-wrap:wrap;gap:10px;}.page-title{font-family:var(--font-h);font-size:1.5rem;font-weight:400;}.empty-state{text-align:center;padding:60px 20px;color:var(--muted);}.empty-state .ei{font-size:2.5rem;margin-bottom:12px;}.empty-state h3{font-family:var(--font-h);font-size:1.2rem;color:var(--ink2);}@media(max-width:768px){.sidebar{transform:translateX(-240px);}.sidebar.open{transform:translateX(0);}.main{margin-left:0;}.content{padding:14px;}.hamburger{display:flex;}}

